#include "gamecube_image.h"

#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
#include <string_view>

namespace fs = std::filesystem;
namespace nectar = pikmin::launcher;

int wmain(int argc, wchar_t* argv[])
{
    if (argc == 2 && std::wstring_view(argv[1]) == L"--help") {
        std::cout << "Open Nectar 1.3 media reader: nectar-extract INPUT.iso OUTPUT_DIRECTORY\n";
        return 0;
    }
    if (argc != 3) return 2;
    const fs::path image = argv[1];
    const fs::path output = argv[2];
    std::error_code error;
    if (!fs::is_regular_file(image, error) || fs::file_size(image, error) != 1459978240 || error ||
        !fs::is_directory(output, error) || !fs::is_empty(output, error) || error) {
        std::cerr << "Expected an original full-size disc and an empty output directory.\n";
        return 1;
    }
    std::ifstream input(image, std::ios::binary);
    nectar::DiscIdentity identity;
    std::string reason;
    if (!input || !nectar::inspectGameCubeImage(input, identity, reason)) {
        std::cerr << reason << '\n';
        return 1;
    }
    const bool supported =
        (identity.gameId == "GPIE01" && identity.revision == 1) ||
        ((identity.gameId == "GPIP01" || identity.gameId == "GPVE01" || identity.gameId == "GPVP01") &&
         identity.revision == 0);
    if (!supported) {
        std::cerr << "Unsupported disc ID or revision.\n";
        return 1;
    }
    input.clear();
    input.seekg(0);
    std::uint32_t previous = 101;
    if (!nectar::extractGameCubeImage(input, 1459978240, output, reason,
        [&previous](std::uint32_t count, std::uint32_t total, const std::string&) {
            const auto percent = total ? static_cast<std::uint64_t>(count) * 100 / total : 0;
            if (percent != previous) {
                previous = static_cast<std::uint32_t>(percent);
                std::cout << "extract=" << percent << '\n' << std::flush;
            }
        }, true)) {
        std::cerr << reason << '\n';
        return 1;
    }
    return 0;
}

